<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_roles(['pengguna']);require __DIR__.'/../../app/helpers/layout.php';render_start('Buku/Skripsi Saya','Semua pengajuan milik akun ini',$u);dashboard_nav('pengguna');render_mid('Buku/Skripsi Saya','Data yang kamu kirim dan status verifikasinya',$u);$st=$pdo->prepare('SELECT * FROM books WHERE submitted_by=? ORDER BY id DESC');$st->execute([$u['id']]);$books=$st->fetchAll();$st=$pdo->prepare("SELECT * FROM repositories WHERE user_id=? AND type='skripsi' ORDER BY id DESC");$st->execute([$u['id']]);$thesis=$st->fetchAll();?><div class="card"><h3>Buku</h3><div class="table-wrap"><table class="table"><thead><tr><th>Judul</th><th>Status</th><th>Tanggal</th></tr></thead><tbody><?php foreach($books as $r):?><tr><td><?=e($r['title'])?></td><td><span class="badge <?=e(status_class($r['approval_status']))?>"><?=e(status_label($r['approval_status']))?></span><?php if($r['rejection_reason']):?><div class="muted"><?=e($r['rejection_reason'])?></div><?php endif;?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;if(!$books):?><tr><td colspan="3" class="empty">Belum ada pengajuan buku.</td></tr><?php endif;?></tbody></table></div><h3 style="margin-top:28px">Skripsi</h3><div class="table-wrap"><table class="table"><thead><tr><th>Judul</th><th>Status</th><th>Tanggal</th></tr></thead><tbody><?php foreach($thesis as $r):?><tr><td><?=e($r['title'])?></td><td><span class="badge <?=e(status_class($r['status']))?>"><?=e(status_label($r['status']))?></span><?php if($r['rejection_reason']):?><div class="muted"><?=e($r['rejection_reason'])?></div><?php endif;?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;if(!$thesis):?><tr><td colspan="3" class="empty">Belum ada pengajuan skripsi.</td></tr><?php endif;?></tbody></table></div></div><?php render_end(); ?>
